/* Links preparation goals to world interactions, commerce and the diary. */
function preparationSummary(){const r=window.VillageProgress?.readiness(game);if(!r)return '';return `<p class="preparation-summary">${r.missing.length?'До ночи: '+r.missing.length+' задач':'Подготовка завершена'}${r.fuel?' · уголь для тотемов: '+game.resources.charcoal+' / '+r.fuel:''}</p>`}
function progressTasksView(){const r=VillageProgress.readiness(game);return `<p>Материалы и зерно — запасы Выселок. Серебро — личный кошелёк Влада: <strong>${game.hero.coins}</strong>.</p><div class="preparation-tasks">${VillageProgress.quests(game).map(q=>`<article class="preparation-task ${q.done?'done':''}"><strong>${q.done?'✓ ':''}${esc(q.title)} · ${q.progress}/${q.goal}</strong><p>${esc(q.desc)}</p></article>`).join('')}</div>${r.shortFuel?`<p class="danger">Не хватает угля: ${r.shortFuel}. Обменяй дерево у Домового.</p>`:''}<div class="row"><button class="ghost" data-action="stationGuards">Назначить дозорных</button><button class="ghost" data-action="villagers">Поговорить с жителями</button><button class="ghost" data-action="journal">Дневник</button></div><h3 class="subhead">Места восстановления</h3><div class="restoration-sites">${(window.village3D?.restorationSites?.()||[]).map(o=>`<button class="ghost" data-action="focusSite" data-id="${esc(o.key)}">${esc(VillageProgress.REPAIRS[o.id]?.name||o.name||o.id)}${VillageProgress.repaired(game,o)?' · готово':' · подойти'}</button>`).join('')}</div><h3 class="subhead">Добыча без расходов</h3><p>Иди к месту заготовки дров или каменной россыпи. Каждый сбор: 6 брёвен или 4 камня. Влад работает на месте; иногда находит верёвку, уголь или лечебную траву. Расчистка леса дополнительно освобождает землю.</p><div class="row"><button class="ghost" data-action="focusGather" data-id="wood">К дровам</button><button class="ghost" data-action="focusGather" data-id="stone">К камню</button></div>`}
function villageProgressModal(m){let title,body;if(m.type==='restoration'){title='Подготовка к ночи '+Math.min(3,game.defense.completed+1);body=progressTasksView()}else if(m.type==='domovoyTalk'){title='Домовой · старый торговый двор';const met=VillageProgress.ensure(game).domovoyMet;VillageProgress.ensure(game).domovoyMet=true;if(!met){discoverCreature('domovoy','first-talk');game.dialogueNotes.push({id:'domovoy-trade-introduction',villagerId:'domovoy',speaker:'Домовой',title:'Припасы и обмен',text:'Для торговли нужно восстановить ряд или палатку. Материалы деревни обмениваются на припасы; зелья и оберег покупаются за серебро Влада.',place:'Выселки',day:game.day})}const wave=game.defense.completed;body=`<p>— ${wave===0?'Серебро береги, Влад. Брёвна и камень здесь найдёшь сам. А крепкую верёвку, краску для знаков и уголь я достану. Только дай мне сухое место: почини ряд или палатку. Три мотка верёвки ещё лежат в деревенских запасах.':wave===1?'Вышка без человека — просто высокая жердь. Собери четыре поста, найди дозорных. А людям почини дома: трудно стоять за деревню, когда в ней негде спать.':'Тотем должен стоять на границе и гореть. Красный знак сам по себе никого не удержит. Уголь принеси заранее — ночью я в лесу, торговаться будет не с кем.'}</p><p>— Для твоего кошелька у меня зелье плакун-травы и оберег бережника. Для деревни — обмен материалов. Не путай одно с другим.</p><div class="row"><button class="ghost" data-action="restoration">План восстановления</button><button class="button" data-action="domovoyTrade">Припасы и обмен</button></div>`;if(!met&&!game.journal.includes('Домовой объяснил обмен: дерево и камень добываются в окрестностях, верёвка, краска и уголь получаются обменом; зелья и оберег оплачиваются серебром Влада.'))game.journal.push('Домовой объяснил обмен: дерево и камень добываются в окрестностях, верёвка, краска и уголь получаются обменом; зелья и оберег оплачиваются серебром Влада.')}else return '';return `<div class="modal-layer"><div class="modal modal-${m.type}" role="dialog" aria-modal="true" aria-label="${title}"><header class="modal-head"><h2>${title}</h2><button class="ghost" data-action="closeModal" aria-label="Закрыть">${brand(87)}</button></header>${body}</div></div>`}
function restorationObjectView(o){const def=window.VillageProgress?.REPAIRS[o.id];let html='';if(def){if(VillageProgress.repaired(game,o))html='<p class="restored-label">Восстановлено · '+esc(def.reward)+'</p>';else html=`<section class="repair-offer"><h3 class="subhead">${def.name}</h3><p>${cardResourceCost(def.cost)}</p><button class="button" data-action="repairObject" ${canAfford(def.cost)?'':'disabled'}>Восстановить</button></section>`}if(o.id==='domovoy')html+='<button class="button" data-action="domovoyTalk">Поговорить с Домовым</button>';if(o.id==='wood_supply'||o.id==='stone_supply')html+=`<p>Не требует материалов. Место можно использовать снова.</p><button class="button" data-action="gather" data-id="${o.id==='wood_supply'?'wood':'stone'}">${o.id==='wood_supply'?'Заготовить 6 брёвен':'Собрать 4 камня'}</button>`;if(o.id==='circle')html+=game.story.ritualMemoryCompleted?'<p class="danger">Влад узнал след обряда. Теперь круг можно разобрать.</p>':'<button class="button" data-action="ritualMemory">Вспомнить обряд</button>';return html}
function restorationDemolitionReason(o){if(!o||!window.VillageProgress)return null;if(['wood_supply','stone_supply'].includes(o.id))return 'Это место добычи нужно для восстановления деревни.';if(o.id==='circle'&&!game.story.ritualMemoryCompleted)return 'Сначала осмотри круг и вспомни обряд.';if(o.id==='chapel')return 'Церковь нужна деревне. Её можно восстановить.';if(o.id==='house_ruin'&&game.defense.completed<3)return 'Этот дом нужен жителям. Восстанови его; старые завалы и частокол можно расчистить.';if(['market_ruin','tent_ruin'].includes(o.id)&&(VillageProgress.repaired(game,o)||!VillageProgress.repairCount(game,'market_ruin')&&!VillageProgress.repairCount(game,'tent_ruin')))return 'Сохрани торговое место для Домового.';return null}
function workInVillage(done){const owner=game;game.ui.openModal=null;render();const complete=()=>{if(game!==owner||owner.phase!=='day'||owner.screen!=='game')return;done()};if(window.village3D?.work){if(!window.village3D.work(complete))notify('Влад занят. Подожди, пока он закончит действие.','error')}else complete()}
function handleVillageProgressAction(action,id){if(!window.VillageProgress)return false;const names=['restoration','repairObject','gather','stationGuards','domovoyTalk','focusSite','focusGather','ritualMemory'];if(!names.includes(action))return false;if(game.phase!=='day'||game.screen!=='game'){notify('Подготовка доступна между ночными боями.','error');return true}if(action==='restoration'){modal('restoration');return true}if(action==='domovoyTalk'){if(!window.village3D?.canTradeDomovoy?.()){notify('Подойди к Домовому, чтобы поговорить.','error');return true}modal('domovoyTalk');return true}if(action==='ritualMemory'){beginRitualMemory();return true}if(action==='focusSite'||action==='focusGather'){game.ui.openModal=null;render();window.village3D?.approach?.(action==='focusGather'?id+'_supply':id);return true}if(action==='stationGuards'){const r=VillageProgress.station(game);if(r.ok){game.journal.push('Четыре жителя назначены на дозорные вышки. Каждый пост прикрывает врагов в радиусе 11 шагов, один выстрел раз в 8 секунд.');render();notify('Дозор занял четыре поста','action')}else notify(r.reason,'error');return true}if(action==='repairObject'){const o=game.ui.openModal?.object;if(!o||!window.village3D?.canWorkAt?.(o)){notify('Подойди ближе к объекту.','error');return true}if(!VillageProgress.canPay(game,VillageProgress.REPAIRS[o.id]?.cost||{})){notify('Не хватает материалов.','error');return true}workInVillage(()=>{const r=VillageProgress.repair(game,o);if(!r.ok){notify(r.reason,'error');return}game.journal.push(r.def.name+'. '+r.def.reward);gainXp(15);render();notify(r.def.name+' · готово','action')});return true}if(action==='gather'){if(!window.village3D?.nearSupply?.(id)){notify('Подойди к месту добычи. Его можно найти в панели восстановления.','error');return true}workInVillage(()=>{const r=VillageProgress.gather(game,id);if(!r.ok)return;if(r.find){const note='Находка в окрестностях: '+r.find.name+'.';if(!game.journal.includes(note))game.journal.push(note)}render();pulseResource(id,r.amount);notify((id==='wood'?'Брёвна':'Камень')+' +'+r.amount+(r.find?' · '+r.find.name:''),'action')});return true}return false}
function restoredHomeConversation(id){if(!window.VillageProgress)return false;const v=game.villagers.find(v=>v.id===id);if(!v?.home||!Object.values(VillageProgress.ensure(game).repairs).some(r=>r.id==='house_ruin'&&r.x===v.home.x&&r.z===v.home.z))return false;const noteId='restored-home-'+id;if(game.dialogueNotes.some(n=>n.id===noteId))return false;const text=id==='marfa'?'Крыша больше не течёт… Я уж отвыкла слышать дождь и не вставать за ведром. Спасибо, Влад. Здесь ещё до разрухи ходили чужие: просили показать старые камни у леса. Говорили тихо, а на рукавах у них были красные знаки. Мы решили, что странники. Теперь думаю: они искали место, где никто не помешает.':'Ты вернул дому опору, а нам — причину остаться. Я выйду на дозор, если поставишь вышки. Только смотри на землю у леса: когда пришли чужие с огнём, там перестала расти трава. Лес потом стал злым. А люди, которые рыли ночью, исчезли раньше первого нападения.';game.dialogueNotes.push({id:noteId,villagerId:id,speaker:v.name,title:'Под восстановленной крышей',text,place:'Выселки',day:game.day});game.journal.push(v.name+': '+text);modal('conversation',{villagerId:id,title:'Под восстановленной крышей',text,fresh:true});return true}
